def create_account(ag_env):
    api_url = ag_env["api_url"]
    auth_key = ag_env["auth_key"]

    headers = {"Authorization": f"Access {auth_key}"}
    url = f"{api_url}/admin/simple/accounts/"

    unique_id = uuid4().hex[:12]

    response = requests.post(
        url=url,
        headers=headers,
